//! VDI **raster** conformance against measured TOS behaviour.
//!
//! The raster group is the one part of the VDI whose result is memory rather
//! than a number, so it needs its own dump format, its own case table and its
//! own harness — see `vdi_raster_reference/harness.rs` for what these tests
//! cover, which fields are deliberately not byte-compared and why. The case
//! module is generated by `tosdump/host/mkrusttests`; do not edit it by hand.
//!
//! Both files live in the `vdi_raster_reference/` subdirectory so cargo does
//! not pick them up as integration-test targets of their own.

#[path = "vdi_raster_reference/harness.rs"]
mod harness;

#[path = "vdi_raster_reference/cases_r1.rs"]
mod cases_r1;
